package com.ricozknow.enterprise.webhook; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/admin/webhooks/dlq") @RequiredArgsConstructor public class WebhookDlqController {private final WebhookDlqService service; @GetMapping @PreAuthorize("hasRole('ADMIN')") public List<WebhookDeadLetter> list(){return service.list();} @PostMapping("/{id}/replay") @PreAuthorize("hasRole('ADMIN')") public WebhookDeadLetter replay(@PathVariable UUID id){return service.replay(id);} }
